        var end=new DateOnly(2026,10,18);var weekStore=new TodoStore(null);weekStore.Add("周一",new(2026,10,12));weekStore.Add("周日",end);weekStore.Add("下周",end.AddDays(1));checks["week_range_is_monday_through_sunday"]=weekStore.ForWeek(end).Count==2&&weekStore.ForWeek(end.AddDays(1)).Single().Title=="下周";
